import React, { useEffect, useMemo, useState } from "react";
import "../styles/battle.css";
import { cards } from "../data/cards";
import { getAvailableReductionsFromBoard, calcActualCost, levelFromCores } from "../utils/bspo";

export default function Battle() {
  const fullDeck = useMemo(() => {
    const deck = [];
    for (let i = 0; i < 20; i++) {
      const c = cards[i % cards.length];
      deck.push({ ...c, deckIndex: i });
    }
    return deck;
  }, []);

  const [me, setMe] = useState({ life: 3, reserve: 4, trash: 0, zones: [null,null,null,null] });
  const [op, setOp] = useState({ life: 5, reserve: 4, trash: 0, zones: [null,null,null,null] });
  const [deck, setDeck] = useState([]);
  const [hand, setHand] = useState([]);
  const [selected, setSelected] = useState(null);

  // 相手用デッキ/手札
  const [opDeck, setOpDeck] = useState([]);
  const [opHand, setOpHand] = useState([]);

  const [turn, setTurn] = useState(0);
  const [step, setStep] = useState(0);

  useEffect(() => {
    const d = [...fullDeck];
    const drawn = [];
    for (let i = 0; i < 4; i++) {
      const idx = Math.floor(Math.random() * d.length);
      drawn.push(d.splice(idx, 1)[0]);
    }
    setDeck(d);
    setHand(drawn);

    const od = [...fullDeck];
    const odrawn = [];
    for (let i = 0; i < 4; i++) {
      const idx = Math.floor(Math.random() * od.length);
      odrawn.push(od.splice(idx, 1)[0]);
    }
    setOpDeck(od);
    setOpHand(odrawn);
  }, [fullDeck]);

  const nextStep = () => {
    if (turn !== 0) return;
    const phase = step % 3;
    if (phase === 0) {
      setMe(m => ({ ...m, reserve: m.reserve + 1 }));
    } else if (phase === 1) {
      if (deck.length > 0) {
        const idx = Math.floor(Math.random() * deck.length);
        const picked = deck[idx];
        const nd = [...deck]; nd.splice(idx,1);
        setDeck(nd);
        setHand(h => [...h, picked]);
      }
    } else {
      setMe(m => ({ ...m, reserve: m.reserve + m.trash, trash: 0 }));
    }
    setStep(s => s + 1);
  };

  const endTurn = () => {
    setTurn(t => (t === 0 ? 1 : 0));
    setStep(0);
  };

  function summonTo(idx) {
    if (turn !== 0) return;
    if (selected === null) return;
    if (me.zones[idx] !== null) return;

    const card = hand[selected];
    const reductions = getAvailableReductionsFromBoard(me.zones);
    const actualCost = calcActualCost(card, reductions);
    const needCores = card.levels[0].core;
    const totalPay = actualCost + needCores;

    if (me.reserve < totalPay) {
      alert(`コア不足：必要${totalPay} / 手持ち${me.reserve}`);
      return;
    }

    const zones = [...me.zones];
    zones[idx] = { card, cores: needCores, attacked: false };

    setMe(m => ({
      ...m,
      reserve: m.reserve - totalPay,
      trash: m.trash + actualCost,
      zones
    }));

    const newHand = [...hand];
    newHand.splice(selected, 1);
    setHand(newHand);
    setSelected(null);
  }

  function levelUp(idx) {
    if (turn !== 0) return;
    const z = me.zones[idx]; if (!z) return;
    const lvNow = levelFromCores(z.card, z.cores);
    const lvArr = z.card.levels;
    const pos = lvArr.findIndex(l => l.lv === lvNow.lv);
    const nextLv = lvArr[pos + 1]; if (!nextLv) return;
    const needMore = nextLv.core - z.cores;
    if (needMore > me.reserve) { alert("コア不足"); return; }

    const zones = [...me.zones];
    zones[idx] = { ...z, cores: nextLv.core };
    setMe(m => ({ ...m, reserve: m.reserve - needMore, zones }));
  }

  function levelDown(idx) {
    if (turn !== 0) return;
    const z = me.zones[idx]; if (!z) return;
    const lvNow = levelFromCores(z.card, z.cores);
    const lvArr = z.card.levels;
    const pos = lvArr.findIndex(l => l.lv === lvNow.lv);
    const prevLv = lvArr[pos - 1]; if (!prevLv) return;

    const refund = z.cores - prevLv.core;
    const zones = [...me.zones];
    zones[idx] = { ...z, cores: prevLv.core };
    setMe(m => ({ ...m, reserve: m.reserve + refund, zones }));
  }

  function attack(idx) {
    if (turn !== 0) return;
    const z = me.zones[idx]; if (!z || z.attacked) return;
    const symbols = z.card.symbolCount || 1;
    setOp(o => ({ ...o, life: Math.max(0, o.life - symbols) }));
    const zones = [...me.zones]; zones[idx] = { ...z, attacked: true };
    setMe(m => ({ ...m, zones }));
  }

  // --- AI関連 ---
  function applyAIMove(move) {
    if (!move) return;
    if (move.type === 'SUMMON') {
      const { handIndex, zoneIndex, pay } = move;
      setOp(prev => {
        const zones = [...prev.zones];
        zones[zoneIndex] = { card: opHand[handIndex], cores: pay.needCores, attacked: false };
        return {
          ...prev,
          zones,
          reserve: prev.reserve - pay.totalPay,
          trash: prev.trash + pay.actualCost,
        };
      });
      setOpHand(h => {
        const nh = [...h];
        nh.splice(handIndex, 1);
        return nh;
      });
    }
    if (move.type === 'LEVEL_UP') {
      setOp(prev => {
        const zones = [...prev.zones];
        const z = zones[move.zoneIndex];
        zones[move.zoneIndex] = { ...z, cores: z.cores + move.needMore };
        return { ...prev, zones, reserve: prev.reserve - move.needMore };
      });
    }
    if (move.type === 'ATTACK') {
      setMe(prev => ({ ...prev, life: Math.max(0, prev.life - (move.symbols || 1)) }));
      setOp(prev => {
        const zones = [...prev.zones];
        const z = zones[move.zoneIndex];
        zones[move.zoneIndex] = { ...z, attacked: true };
        return { ...prev, zones };
      });
    }
  }

  useEffect(() => {
    async function askAI() {
      if (turn !== 1) return;
      setOp(prev => ({ ...prev, zones: prev.zones.map(z => z ? { ...z, attacked: false } : z) }));
      const state = { me, op, opHand, opDeckCount: opDeck.length };
      try {
        const resp = await fetch('http://localhost:4000/ai/move', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ state, mode: 'heuristic' })
        });
        const json = await resp.json();
        if (json.ok) {
          applyAIMove(json.move);
          console.log('AI:', json.explanation);
        } else {
          console.warn('AI error', json.error);
        }
      } catch (e) {
        console.error(e);
      } finally {
        setTurn(0);
        setStep(0);
      }
    }
    askAI();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [turn]);

  return (
    <div className="board">
      <div className="hud" style={{gridColumn:"1 / -1", justifyContent:"space-between"}}>
        <div style={{display:"flex", gap:16}}>
          <span>手番: <b>{turn === 0 ? "あなた" : "相手（AI）"}</b></span>
          <span>ステップ: <b>{(step % 3) + 1} / 3</b></span>
        </div>
        <div style={{display:"flex", gap:10}}>
          <button className="next-btn" onClick={nextStep} disabled={turn!==0}>次のステップ</button>
          <button className="next-btn" onClick={endTurn}>ターン終了</button>
        </div>
      </div>

      <section className="side my-side">
        <header className="hud">
          <span>LIFE <b>{me.life}</b></span>
          <span>RESERVE <b>{me.reserve}</b></span>
          <span>TRASH <b>{me.trash}</b></span>
        </header>

        <div className="field">
          {me.zones.map((z, i) =>
            !z ? (
              <div key={i} className={`zone ${selected!==null && turn===0 ? "placeable": ""}`} onClick={() => summonTo(i)}>
                <span>ゾーン{i+1}</span>
              </div>
            ) : (
              <div key={i} className="zone filled">
                <img src={z.card.img} alt={z.card.name} className="zone-card"/>
                <div className="zone-badge">Lv{levelFromCores(z.card, z.cores).lv}</div>
                <div className="zone-controls">
                  <button className="btn-small" onClick={() => levelDown(i)}>-</button>
                  <button className="btn-small" onClick={() => levelUp(i)}>+</button>
                  <button className="btn-small warn" disabled={z.attacked} onClick={() => attack(i)}>ATK</button>
                </div>
              </div>
            )
          )}
        </div>

        <footer className="hand hand-bottom">
          {hand.length===0 ? <span>手札ゾーン</span> : (
            <div className="hand-cards">
              {hand.map((c, i) => (
                <img key={c.deckIndex} src={c.img} alt={c.name}
                  className={`card-img ${selected===i ? "selected": ""}`}
                  onClick={() => setSelected(prev => prev===i ? null : i)} />
              ))}
            </div>
          )}
        </footer>
      </section>

      <div className="divider" />

      <section className="side op-side">
        <header className="hand hand-top"><span>V手札ゾーン</span></header>

        <div className="field">
          {op.zones.map((z,i) =>
            !z ? <div key={i} className="zone"><span>{i+1}ゾーン</span></div>
               : <div key={i} className="zone filled">
                   <img className="zone-card" src={z.card.img} alt={z.card.name}/>
                 </div>
          )}
        </div>

        <footer className="hud">
          <span className="hud-item red">LIFE <b>{op.life}</b></span>
          <span className="hud-item red">RESERVE <b>{op.reserve}</b></span>
          <span className="hud-item red">TRASH <b>{op.trash}</b></span>
        </footer>
      </section>
    </div>
  );
}
